# Practical 3: Control Flow - if, elif, else

def grade_calculator(marks):
    """Return letter grade and remark based on marks."""
    if marks >= 90:
        grade = 'A+'
        remark = 'Outstanding'
    elif marks >= 80:
        grade = 'A'
        remark = 'Excellent'
    elif marks >= 70:
        grade = 'B'
        remark = 'Good'
    elif marks >= 60:
        grade = 'C'
        remark = 'Average'
    elif marks >= 40:
        grade = 'D'
        remark = 'Pass'
    else:
        grade = 'F'
        remark = 'Fail'
    return grade, remark

def check_number(n):
    """Check properties of a number."""
    if n > 0:
        print(f"{n} is positive")
    elif n < 0:
        print(f"{n} is negative")
    else:
        print(f"{n} is zero")

    if n % 2 == 0:
        print(f"{n} is even")
    else:
        print(f"{n} is odd")

