def safe_divide(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        print("  Error: Cannot divide by zero.")
        return None
    except TypeError as e:
        print(f"  TypeError: {e}")
        return None
    finally:
        print("  (division attempt completed)")

def parse_integer(val):
    try:
        return int(val)
    except (ValueError, TypeError):
        return -1

