# Practical 2: Stack - Push, Pop, Peek

class Stack:
    def __init__(self):
        self._items = []

    def push(self, item):
        self._items.append(item)

    def pop(self):
        if self.is_empty():
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def peek(self):
        if self.is_empty():
            raise IndexError("peek at empty stack")
        return self._items[-1]

    def is_empty(self):
        return len(self._items) == 0

    def size(self):
        return len(self._items)

def is_balanced(expression):
    stack = Stack()
    brackets = {')': '(', '}': '{', ']': '['}
    for char in expression:
        if char in "({[":
            stack.push(char)
        elif char in ")}]":
            if stack.is_empty() or stack.pop() != brackets[char]:
                return False
    return stack.is_empty()

def main():
    s = Stack()
    for v in [10, 20, 30]:
        s.push(v)
    print("Top element:", s.peek())
    print("Popped:", s.pop())
    print("Size:", s.size())

    print("\nBracket checks:")
    for expr in ["{[()]}", "{[(])}", "((())"]:
        print(f"  '{expr}' -> {is_balanced(expr)}")

if __name__ == "__main__":
    main()

# Practical 3: Queue - Enqueue and Dequeue
from collections import deque

class Queue:
    def __init__(self):
        self._data = deque()

    def enqueue(self, item):
        self._data.append(item)

    def dequeue(self):
        if self.is_empty():
            raise IndexError("dequeue from empty queue")
        return self._data.popleft()

    def front(self):
        if self.is_empty():
            raise IndexError("queue is empty")
        return self._data[0]

    def is_empty(self):
        return len(self._data) == 0

    def size(self):
        return len(self._data)

def main():
    q = Queue()
    for task in ["Task 1", "Task 2", "Task 3"]:
        q.enqueue(task)
        print(f"Enqueued: {task}")

    print(f"\nFront element: {q.front()}")
    print("Dequeuing tasks:")
    while not q.is_empty():
        print(f"  Processing: {q.dequeue()}")

