    main()

# Practical 6: Sorting Algorithms

def bubble_sort(arr):
    a = arr.copy()
    n = len(a)
    for i in range(n):
        swapped = False
        for j in range(0, n - i - 1):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
                swapped = True
        if not swapped:
            break
    return a

def selection_sort(arr):
    a = arr.copy()
    n = len(a)
    for i in range(n):
        min_idx = i
        for j in range(i + 1, n):
            if a[j] < a[min_idx]:
                min_idx = j
        a[i], a[min_idx] = a[min_idx], a[i]
    return a

def insertion_sort(arr):
    a = arr.copy()
    for i in range(1, len(a)):
        key = a[i]
        j = i - 1
        while j >= 0 and a[j] > key:
            a[j + 1] = a[j]
            j -= 1
        a[j + 1] = key
    return a

def main():
    data = [64, 34, 25, 12, 22, 11, 90]
    print("Original:       ", data)
    print("Bubble Sort:    ", bubble_sort(data))
    print("Selection Sort: ", selection_sort(data))
    print("Insertion Sort: ", insertion_sort(data))

if __name__ == "__main__":
    main()

# Practical 7: Hash Table with Chaining

class HashTable:
    def __init__(self, size=10):
        self.size = size
        self.table = [[] for _ in range(size)]

    def _hash(self, key):
        return hash(key) % self.size

    def put(self, key, value):
        idx = self._hash(key)
        for i, (k, v) in enumerate(self.table[idx]):
            if k == key:
                self.table[idx][i] = (key, value)
                return
        self.table[idx].append((key, value))

    def get(self, key, default=None):
        idx = self._hash(key)
        for k, v in self.table[idx]:
            if k == key:
                return v
        return default

def main():
    ht = HashTable(size=7)
    ht.put("apple", 1.50)
    ht.put("banana", 0.75)
    ht.put("cherry", 2.25)

    print("apple  ->", ht.get("apple"))
    print("banana ->", ht.get("banana"))
    print("orange ->", ht.get("orange", "Not found"))

if __name__ == "__main__":
