# Practical 8: Graph - BFS and DFS
from collections import deque

class Graph:
    def __init__(self):
        self.adj = {}

    def add_edge(self, u, v):
        self.adj.setdefault(u, []).append(v)
        self.adj.setdefault(v, []).append(u)

    def bfs(self, start):
        visited = {start}
        order = []
        q = deque([start])
        while q:
            node = q.popleft()
            order.append(node)
            for neighbor in self.adj.get(node, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    q.append(neighbor)
        return order

    def dfs(self, start):
        visited = set()
        order = []
        def _dfs(node):
            visited.add(node)
            order.append(node)
            for neighbor in self.adj.get(node, []):
                if neighbor not in visited:
                    _dfs(neighbor)
        _dfs(start)
        return order

def main():
    g = Graph()
    edges = [(1, 2), (1, 3), (2, 4), (2, 5), (3, 6)]
    for u, v in edges:
        g.add_edge(u, v)

    print("BFS from 1:", g.bfs(1))
    print("DFS from 1:", g.dfs(1))

if __name__ == "__main__":
    main()

# Practical 9: Merge Sort and Quick Sort

def merge_sort(arr):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)

def merge(left, right):
    res = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            res.append(left[i]); i += 1
        else:
            res.append(right[j]); j += 1
    res.extend(left[i:])
    res.extend(right[j:])
    return res

def quick_sort(arr):
    if len(arr) <= 1:
        return arr
    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quick_sort(left) + middle + quick_sort(right)

def main():
    arr = [38, 27, 43, 3, 9, 82, 10]
    print("Input:     ", arr)
    print("Merge Sort:", merge_sort(arr))
    print("Quick Sort:", quick_sort(arr))

if __name__ == "__main__":
    main()

# Practical 10: Heap and Priority Queue
import heapq

class PriorityQueue:
    def __init__(self):
        self._queue = []
        self._index = 0

    def push(self, item, priority):
        heapq.heappush(self._queue, (priority, self._index, item))
        self._index += 1

    def pop(self):
        return heapq.heappop(self._queue)[-1]

    def is_empty(self):
        return len(self._queue) == 0

def main():
    pq = PriorityQueue()
    pq.push("Bug Fix", 3)
    pq.push("Critical Outage", 1)
    pq.push("Code Review", 2)

    print("Serving tasks in priority order:")
    while not pq.is_empty():
        print("  Processed:", pq.pop())

